/* DSA track visualisers. Frames are generated by running the real algorithm. */
(function () {
  const { h, s, clear, button, row, caption, seg, range, chip, stat, stepper } = window.VZ;
  const add = window.PNODE_VIZ.add;

  // array strip: values with highlight classes and pointer labels underneath
  function strip(values, opts) {
    opts = opts || {};
    const cls = opts.cls || {}, ptr = opts.ptr || {};
    return h("div", { class: "vscroll" }, h("div", { style: `display:grid;grid-template-columns:repeat(${values.length}, minmax(32px, 1fr));gap:4px;min-width:${values.length * 36}px` },
      ...values.map((v, i) => h("div", { style: "display:grid;gap:2px;text-align:center" },
        h("div", { class: "vitem " + (cls[i] || ""), style: "font:700 0.95rem var(--f-code);padding:8px 2px;text-align:center" }, String(v)),
        h("div", { style: "font:0.65rem var(--f-code);color:var(--ink-3)" }, String(i)),
        h("div", { style: "font:700 0.72rem var(--f-body);color:var(--lit);min-height:1em" }, ptr[i] || "")))));
  }
  function frames(root, ctx, F, draw, speed) {
    const host = h("div", { style: "display:grid;gap:10px" });
    const cap = caption();
    const st = stepper(ctx, { count: () => F().length, speed: speed || 1100, render(i) { const f = F()[i]; clear(host); draw(host, f, i); cap.textContent = f.say; } });
    root.append(host, cap, st.el);
    return st;
  }

  // ---------------------------------------------------------------- Big-O
  add({
    id: "big-o",
    title: "How fast does it grow?",
    blurb: "Slide n and compare the complexity classes",
    nodes: ["dsa-big-o"],
    mount(root) {
      let exp = 3;
      const host = h("div", { class: "vstack" });
      const cap = caption();
      const classes = [["O(1)", () => 1, "--mint"], ["O(log n)", (n) => Math.log2(n), "--mint"], ["O(n)", (n) => n, "--sky"], ["O(n log n)", (n) => n * Math.log2(n), "--sky"], ["O(n²)", (n) => n * n, "--lit"], ["O(2ⁿ)", (n) => Math.pow(2, Math.min(n, 1024)), "--danger"]];
      const human = (ops) => { const sec = ops / 1e8; if (!isFinite(sec) || sec > 3e17) return "longer than the age of the universe"; if (sec < 1e-6) return "instant"; if (sec < 1e-3) return (sec * 1e6).toFixed(1) + " µs"; if (sec < 1) return (sec * 1e3).toFixed(1) + " ms"; if (sec < 60) return sec.toFixed(1) + " s"; if (sec < 3600) return (sec / 60).toFixed(1) + " min"; if (sec < 86400) return (sec / 3600).toFixed(1) + " hours"; if (sec < 3.15e7) return (sec / 86400).toFixed(0) + " days"; return (sec / 3.15e7).toExponential(1) + " years"; };
      function draw() {
        const n = Math.round(Math.pow(10, exp));
        clear(host);
        const maxLog = 20;
        classes.forEach(([label, f, col]) => {
          const ops = f(n);
          const lg = Math.log10(Math.max(1, ops));
          const w = Math.min(100, (lg / maxLog) * 100);
          host.appendChild(h("div", { style: "display:grid;grid-template-columns:88px 1fr;gap:8px;align-items:center" },
            h("b", { style: "font:700 0.85rem var(--f-code)" }, label),
            h("div", null, h("div", { style: "height:12px;background:var(--bg-raised);border:1px solid var(--line);border-radius:99px;overflow:hidden" }, h("div", { style: `height:100%;width:${Math.max(1, w)}%;background:var(${col})` })),
              h("div", { class: "small muted", style: "margin-top:2px" }, `${ops > 1e15 ? "10^" + lg.toFixed(0) : Math.round(ops).toLocaleString()} steps · ${human(ops)}`))));
        });
        cap.textContent = `n = ${n.toLocaleString()}. At roughly 100 million simple steps per second, O(n log n) still feels instant while O(n²) ${n >= 1e5 ? "takes far too long" : "is getting slow"}. Interview limits: n up to 10⁵ usually means you need O(n log n) or better. (Bar length uses a log scale.)`;
      }
      root.append(range("input size n", { min: 1, max: 7, step: 0.5, value: exp, fmt: (x) => Math.round(Math.pow(10, x)).toLocaleString() }, (x) => { exp = x; draw(); }).el, host, cap);
      draw();
    },
  });

  // ---------------------------------------------------------------- two-sum with hash map
  add({
    id: "two-sum-hash",
    title: "Hash map: one pass instead of two loops",
    blurb: "Find two numbers that add up to the target",
    nodes: ["dsa-arrays-hashing"],
    mount(root, ctx) {
      const arr = [8, 3, 11, 5, 7, 2, 9];
      let target = 12;
      function gen() {
        const F = [], seen = new Map();
        F.push({ i: -1, map: [], say: `Target ${target}. Brute force tries every pair: up to ${arr.length * (arr.length - 1) / 2} checks, O(n²). Instead, remember what you've seen.` });
        for (let i = 0; i < arr.length; i++) {
          const need = target - arr[i];
          if (seen.has(need)) { F.push({ i, j: seen.get(need), map: [...seen], found: true, say: `${arr[i]} needs ${need}. The map has ${need} at index ${seen.get(need)}. Found in ${i + 1} steps with one O(1) lookup each: O(n) time, O(n) space.` }); return F; }
          F.push({ i, map: [...seen], need, say: `${arr[i]} needs ${need}. Not in the map yet, so store ${arr[i]} → index ${i}.` });
          seen.set(arr[i], i);
          F[F.length - 1].map = [...seen];
        }
        F.push({ i: -1, map: [...seen], say: "No pair adds up to the target." });
        return F;
      }
      let F = gen();
      const sg = seg([9, 12, 16, 30].map((t) => ({ v: t, label: "target " + t })), target, (v) => { target = v; F = gen(); st.stop(); st.go(0); }, "Target");
      root.appendChild(sg.el);
      const st = frames(root, ctx, () => F, (host, f) => {
        const cls = {}, ptr = {};
        if (f.i >= 0) { cls[f.i] = "lit"; ptr[f.i] = "i"; }
        if (f.found) { cls[f.i] = "mint"; cls[f.j] = "mint"; ptr[f.j] = "match"; }
        host.append(strip(arr, { cls, ptr }), h("div", { class: "vbox" }, h("h4", null, "seen: value → index"), h("div", { class: "vrow" }, f.map.length ? f.map.map(([k, v]) => chip(`${k} → ${v}`, f.need === k ? "lit" : "sky")) : h("span", { class: "small muted" }, "empty"))));
      });
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- two pointers
  add({
    id: "two-pointers",
    title: "Two pointers on a sorted array",
    blurb: "Move the pointer that gets you closer",
    nodes: ["dsa-two-pointers"],
    mount(root, ctx) {
      const arr = [1, 3, 4, 6, 8, 11, 14, 17];
      let target = 20;
      function gen() {
        const F = []; let l = 0, r = arr.length - 1;
        while (l < r) {
          const sum = arr[l] + arr[r];
          if (sum === target) { F.push({ l, r, ok: true, say: `${arr[l]} + ${arr[r]} = ${target}. Found in ${F.length + 1} steps. O(n) time, O(1) extra space, because the array is sorted.` }); return F; }
          F.push({ l, r, say: sum < target ? `${arr[l]} + ${arr[r]} = ${sum}, too small. Every pair using ${arr[l]} would be too small too, so move left → .` : `${arr[l]} + ${arr[r]} = ${sum}, too big. Every pair using ${arr[r]} is too big, so move right ←.` });
          if (sum < target) l++; else r--;
        }
        F.push({ l, r, none: true, say: "The pointers met. No pair adds up to the target." });
        return F;
      }
      let F = gen();
      const sg = seg([20, 25, 13, 2].map((t) => ({ v: t, label: "target " + t })), target, (v) => { target = v; F = gen(); st.stop(); st.go(0); }, "Target");
      root.appendChild(sg.el);
      const st = frames(root, ctx, () => F, (host, f) => {
        const cls = {}, ptr = {};
        cls[f.l] = f.ok ? "mint" : "lit"; cls[f.r] = f.ok ? "mint" : "sky"; ptr[f.l] = "L"; ptr[f.r] = (ptr[f.r] ? ptr[f.r] + " " : "") + "R";
        for (let i = 0; i < arr.length; i++) if (i < f.l || i > f.r) cls[i] = "dim";
        host.append(strip(arr, { cls, ptr }), h("div", { class: "vstats" }, stat("sum", arr[f.l] + arr[f.r], f.ok ? "good" : ""), stat("target", target)));
      });
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- sliding window
  add({
    id: "sliding-window",
    title: "Sliding window",
    blurb: "Longest substring without repeating characters",
    nodes: ["dsa-sliding-window"],
    mount(root, ctx) {
      let str = "abcabcbb";
      function gen() {
        const F = [], last = new Map(); let l = 0, best = 0, bestL = 0;
        for (let r = 0; r < str.length; r++) {
          const c = str[r];
          if (last.has(c) && last.get(c) >= l) { const old = l; l = last.get(c) + 1; F.push({ l, r, best, bestL, say: `"${c}" is already inside the window (index ${last.get(c)}). Jump left from ${old} to ${l}, past the old "${c}". The left pointer never moves backwards.` }); }
          last.set(c, r);
          if (r - l + 1 > best) { best = r - l + 1; bestL = l; }
          F.push({ l, r, best, bestL, say: `Expand right to "${c}". Window "${str.slice(l, r + 1)}" has no repeats. Best so far: ${best}.` });
        }
        F.push({ l: bestL, r: bestL + best - 1, best, bestL, done: true, say: `Answer: "${str.slice(bestL, bestL + best)}", length ${best}. Each character enters and leaves the window at most once: O(n), instead of checking every substring (O(n²) or worse).` });
        return F;
      }
      let F = gen();
      const sg = seg(["abcabcbb", "pwwkew", "mangaluru"].map((v) => ({ v, label: `"${v}"` })), str, (v) => { str = v; F = gen(); st.stop(); st.go(0); }, "Input string");
      root.appendChild(sg.el);
      const st = frames(root, ctx, () => F, (host, f) => {
        const cls = {}, ptr = {};
        for (let i = 0; i < str.length; i++) cls[i] = i >= f.l && i <= f.r ? (f.done ? "mint" : "lit") : "";
        ptr[f.l] = "L"; ptr[f.r] = (ptr[f.r] ? "L R" : "R");
        host.append(strip(str.split(""), { cls, ptr }), h("div", { class: "vstats" }, stat("window size", f.r - f.l + 1), stat("best", f.best, "good")));
      }, 1000);
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- binary search
  add({
    id: "binary-search",
    title: "Binary search",
    blurb: "Halve the search space every step",
    nodes: ["dsa-binary-search"],
    mount(root, ctx) {
      const arr = [2, 5, 8, 12, 16, 23, 38, 42, 56, 64, 72, 81, 90, 95, 99];
      let target = 72;
      function gen() {
        const F = []; let lo = 0, hi = arr.length - 1;
        while (lo <= hi) {
          const mid = lo + ((hi - lo) >> 1);
          if (arr[mid] === target) { F.push({ lo, hi, mid, ok: true, say: `arr[${mid}] = ${target}. Found in ${F.length + 1} checks out of ${arr.length} items. log₂(15) ≈ 4.` }); return F; }
          F.push({ lo, hi, mid, say: `mid = ${mid}, arr[mid] = ${arr[mid]}. ${arr[mid] < target ? `Too small, so the answer must be right of mid: lo = ${mid + 1}.` : `Too big, so the answer must be left of mid: hi = ${mid - 1}.`}` });
          if (arr[mid] < target) lo = mid + 1; else hi = mid - 1;
        }
        F.push({ lo, hi, mid: -1, say: `lo (${lo}) passed hi (${hi}). ${target} isn't in the array, and lo = ${lo} is exactly where it would be inserted. That insertion-point trick solves many "first/last position" problems.` });
        return F;
      }
      let F = gen();
      const sg = seg([72, 16, 99, 50].map((t) => ({ v: t, label: "find " + t })), target, (v) => { target = v; F = gen(); st.stop(); st.go(0); }, "Target");
      root.appendChild(sg.el);
      const st = frames(root, ctx, () => F, (host, f) => {
        const cls = {}, ptr = {};
        for (let i = 0; i < arr.length; i++) cls[i] = i < f.lo || i > f.hi ? "dim" : "";
        if (f.mid >= 0) { cls[f.mid] = f.ok ? "mint" : "lit"; ptr[f.mid] = "mid"; }
        if (f.lo < arr.length) ptr[f.lo] = (ptr[f.lo] ? ptr[f.lo] + " " : "") + "lo";
        if (f.hi >= 0) ptr[f.hi] = (ptr[f.hi] ? ptr[f.hi] + " " : "") + "hi";
        host.append(strip(arr, { cls, ptr }), h("p", { class: "small muted", style: "margin:0" }, "Use mid = lo + (hi - lo) / 2 to avoid integer overflow in languages with fixed-size ints."));
      });
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- linked list reverse
  add({
    id: "linked-list-reverse",
    title: "Reverse a linked list",
    blurb: "Three pointers: prev, curr, next",
    nodes: ["dsa-linked-lists"],
    mount(root, ctx) {
      const vals = [1, 2, 3, 4];
      const F = [];
      let nexts = [1, 2, 3, null], prev = null, curr = 0;
      F.push({ nexts: nexts.slice(), prev, curr, nxt: null, say: "prev = null, curr = head. Each step: save next, point curr back at prev, then move both forward." });
      while (curr != null) {
        const nxt = nexts[curr];
        F.push({ nexts: nexts.slice(), prev, curr, nxt, say: `Save next = ${nxt == null ? "null" : vals[nxt]} before we lose it.` });
        nexts[curr] = prev;
        F.push({ nexts: nexts.slice(), prev, curr, nxt, say: `Point ${vals[curr]}.next back to ${prev == null ? "null" : vals[prev]}. The link is flipped.` });
        prev = curr; curr = nxt;
        F.push({ nexts: nexts.slice(), prev, curr, nxt: null, say: `Move forward: prev = ${vals[prev]}, curr = ${curr == null ? "null" : vals[curr]}.` });
      }
      F.push({ nexts: nexts.slice(), prev, curr: null, nxt: null, done: true, say: "curr is null, so prev is the new head: 4 → 3 → 2 → 1 → null. O(n) time, O(1) space." });
      const st = frames(root, ctx, () => F, (host, f) => {
        const wrap = h("div", { class: "vscroll" });
        const line = h("div", { style: "display:flex;align-items:flex-start;gap:4px;min-width:340px;padding:4px 0" });
        const arrow = (t) => h("div", { style: "align-self:center;color:var(--lit);font-weight:800;min-width:14px;text-align:center;margin-top:-14px" }, t);
        const node = (txt, cls, lab) => h("div", { style: "text-align:center;min-width:44px" }, h("div", { class: "vitem " + (cls || ""), style: `font:700 ${txt === "null" ? "0.72rem" : "1rem"} var(--f-code);padding:${txt === "null" ? "11px 2px" : "8px 4px"};white-space:nowrap` }, txt), h("div", { style: "font:700 .72rem var(--f-body);color:var(--lit);min-height:1em" }, lab || ""));
        line.appendChild(node("null", "", f.prev == null && !f.done ? "prev" : ""));
        line.appendChild(arrow(f.nexts[0] === null ? "←" : " "));
        vals.forEach((v, i) => {
          const lab = [f.prev === i ? "prev" : "", f.curr === i ? "curr" : "", f.nxt === i ? "next" : ""].filter(Boolean).join(" ");
          line.appendChild(node(String(v), f.curr === i ? "lit" : f.prev === i ? "mint" : f.nxt === i ? "sky" : "", lab));
          if (i < vals.length - 1) line.appendChild(arrow(f.nexts[i] === i + 1 ? "→" : f.nexts[i + 1] === i ? "←" : "✂"));
        });
        line.appendChild(arrow(f.nexts[3] === null ? "→" : " "));
        line.appendChild(node("null", "", f.curr == null ? "curr" : ""));
        wrap.appendChild(line);
        host.append(wrap, h("div", { class: "small muted" }, "next pointers: " + vals.map((v, i) => `${v}→${f.nexts[i] == null ? "null" : vals[f.nexts[i]]}`).join("   ")));
      });
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- stack brackets
  add({
    id: "stack-brackets",
    title: "Stack: valid brackets",
    blurb: "Last opened, first closed",
    nodes: ["dsa-linked-lists"],
    mount(root, ctx) {
      let str = "{[()()]}";
      const pairs = { ")": "(", "]": "[", "}": "{" };
      function gen() {
        const F = [], stack = [];
        F.push({ i: -1, stack: [], say: "Push every opening bracket. On a closing bracket, the top of the stack must be its partner." });
        for (let i = 0; i < str.length; i++) {
          const c = str[i];
          if ("([{".includes(c)) { stack.push(c); F.push({ i, stack: stack.slice(), say: `"${c}" opens. Push it.` }); }
          else {
            const top = stack[stack.length - 1];
            if (top !== pairs[c]) { F.push({ i, stack: stack.slice(), bad: true, say: `"${c}" closes, but the top is ${top ? `"${top}"` : "empty"}. Invalid.` }); return F; }
            stack.pop(); F.push({ i, stack: stack.slice(), say: `"${c}" matches the top "${pairs[c]}". Pop it.` });
          }
        }
        F.push({ i: str.length, stack: stack.slice(), bad: stack.length > 0, done: true, say: stack.length ? `End of string with ${stack.length} unclosed bracket(s) left. Invalid.` : "End of string and the stack is empty. Valid. O(n) time." });
        return F;
      }
      let F = gen();
      const sg = seg(["{[()()]}", "([)]", "(()"].map((v) => ({ v, label: v })), str, (v) => { str = v; F = gen(); st.stop(); st.go(0); }, "Input");
      root.appendChild(sg.el);
      const st = frames(root, ctx, () => F, (host, f) => {
        const cls = {}; for (let i = 0; i < str.length; i++) cls[i] = i < f.i ? "dim" : i === f.i ? (f.bad ? "bad" : "lit") : "";
        host.append(strip(str.split(""), { cls }), h("div", { class: "vbox" }, h("h4", null, "stack (top on the right)"), h("div", { class: "vrow" }, f.stack.length ? f.stack.map((c, i) => chip(c, i === f.stack.length - 1 ? "lit" : "")) : h("span", { class: "small muted" }, "empty"))));
      }, 900);
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- recursion tree
  add({
    id: "recursion-subsets",
    title: "Backtracking: all subsets of [1, 2, 3]",
    blurb: "At each level, choose: take it or skip it",
    nodes: ["dsa-recursion"],
    mount(root, ctx) {
      const nums = [1, 2, 3];
      const nodes = [];
      (function build(d, k, path) { nodes.push({ d, k, path }); if (d === nums.length) return; build(d + 1, k * 2, path); build(d + 1, k * 2 + 1, path.concat(nums[d])); })(0, 0, []);
      const order = [];
      (function dfs(d, k) { order.push(nodes.find((n) => n.d === d && n.k === k)); if (d === nums.length) return; dfs(d + 1, k * 2); dfs(d + 1, k * 2 + 1); })(0, 0);
      const F = order.map((n, i) => {
        const results = order.slice(0, i + 1).filter((x) => x.d === nums.length).map((x) => "[" + x.path.join(",") + "]");
        return { n, visited: order.slice(0, i + 1), results, say: n.d === nums.length ? `Leaf: no numbers left to decide, so record [${n.path.join(", ")}]. Return and undo the last choice (that's the "back" in backtracking).` : n.d === 0 ? "Start with an empty subset. Decide about 1 first." : `Path so far [${n.path.join(", ")}]. Now decide about ${nums[n.d]}: skip it (left) or take it (right).` };
      });
      F[F.length - 1].say += " All 2³ = 8 subsets found. Time O(n · 2ⁿ).";
      const st = frames(root, ctx, () => F, (host, f) => {
        const W = 360, H = 200;
        const svg = s("svg", { class: "vsvg", viewBox: `0 0 ${W} ${H}`, style: "max-width:560px;margin:0 auto", role: "img", "aria-label": "Recursion tree" });
        const pos = (n) => [((n.k + 0.5) / Math.pow(2, n.d)) * W, 20 + n.d * 55];
        nodes.forEach((n) => { if (!n.d) return; const parent = nodes.find((p) => p.d === n.d - 1 && p.k === n.k >> 1); const [x1, y1] = pos(parent), [x2, y2] = pos(n); const on = f.visited.includes(n); svg.appendChild(s("line", { x1, y1, x2, y2, class: on ? "s-lit" : "s-line", "stroke-width": on ? 2 : 1 })); svg.appendChild(s("text", { x: (x1 + x2) / 2 + (n.k % 2 ? 6 : -6), y: (y1 + y2) / 2, "font-size": 9, "text-anchor": n.k % 2 ? "start" : "end", class: "t-dim" }, n.k % 2 ? `+${nums[n.d - 1]}` : "skip")); });
        nodes.forEach((n) => { const [x, y] = pos(n); const on = f.visited.includes(n), cur = f.n === n; const label = "[" + n.path.join(",") + "]"; const w = Math.max(26, label.length * 6.5); svg.appendChild(s("rect", { x: x - w / 2, y: y - 10, width: w, height: 20, rx: 6, class: cur ? "f-lit" : on ? (n.d === 3 ? "f-mint" : "f-sky") : "f-raised s-line" })); svg.appendChild(s("text", { x, y: y + 4, "text-anchor": "middle", "font-size": 9.5, "font-weight": 700, class: (cur || on) ? "t-ink-on-lit mono" : "t-dim mono" }, label)); });
        host.append(svg, h("div", { class: "vrow" }, h("span", { class: "small muted" }, "results:"), ...f.results.map((r) => chip(r, "mint"))));
      }, 800);
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- tree traversals
  add({
    id: "tree-traversals",
    title: "Tree traversals",
    blurb: "Same tree, four visiting orders",
    nodes: ["dsa-trees"],
    mount(root, ctx) {
      const T = { v: 8, l: { v: 4, l: { v: 2 }, r: { v: 6 } }, r: { v: 12, l: { v: 10 }, r: { v: 14 } } };
      const place = [];
      (function p(n, d, x0, x1) { if (!n) return; n.x = (x0 + x1) / 2; n.y = 26 + d * 58; place.push(n); p(n.l, d + 1, x0, n.x); p(n.r, d + 1, n.x, x1); })(T, 0, 0, 340);
      const orders = {
        pre: { label: "Preorder", f: (n, o) => { if (!n) return; o.push(n); orders.pre.f(n.l, o); orders.pre.f(n.r, o); }, say: "Node, then left, then right. Used to copy or serialise a tree." },
        in: { label: "Inorder", f: (n, o) => { if (!n) return; orders.in.f(n.l, o); o.push(n); orders.in.f(n.r, o); }, say: "Left, node, right. On a binary search tree this visits values in sorted order: a favourite interview fact." },
        post: { label: "Postorder", f: (n, o) => { if (!n) return; orders.post.f(n.l, o); orders.post.f(n.r, o); o.push(n); }, say: "Left, right, then node. Children finish before parents: used for deleting a tree or computing heights and sizes." },
        level: { label: "Level order", f: (n, o) => { const q = [n]; while (q.length) { const x = q.shift(); o.push(x); if (x.l) q.push(x.l); if (x.r) q.push(x.r); } }, say: "Breadth-first with a queue, level by level. Used for \"minimum depth\" or printing each level." },
      };
      let mode = "in";
      let F = [];
      function gen() { const o = []; orders[mode].f(T, o); F = o.map((n, i) => ({ seen: o.slice(0, i + 1), say: i === o.length - 1 ? orders[mode].say : `Visit ${n.v}.` })); }
      gen();
      const sg = seg(Object.entries(orders).map(([v, o]) => ({ v, label: o.label })), mode, (v) => { mode = v; gen(); st.stop(); st.go(0); }, "Traversal");
      root.appendChild(sg.el);
      const st = frames(root, ctx, () => F, (host, f) => {
        const svg = s("svg", { class: "vsvg", viewBox: "0 0 340 190", style: "max-width:480px;margin:0 auto", role: "img", "aria-label": "Binary search tree" });
        place.forEach((n) => [n.l, n.r].forEach((c) => c && svg.appendChild(s("line", { x1: n.x, y1: n.y, x2: c.x, y2: c.y, class: "s-line", "stroke-width": 2 }))));
        place.forEach((n) => { const i = f.seen.indexOf(n), cur = i === f.seen.length - 1; svg.appendChild(s("circle", { cx: n.x, cy: n.y, r: 17, class: cur ? "f-lit" : i >= 0 ? "f-mint" : "f-raised s-line", "stroke-width": 1.5 })); svg.appendChild(s("text", { x: n.x, y: n.y + 5, "text-anchor": "middle", "font-size": 14, "font-weight": 700, class: i >= 0 ? "t-ink-on-lit" : "" }, String(n.v))); if (i >= 0) svg.appendChild(s("text", { x: n.x + 20, y: n.y - 12, "font-size": 10, class: "t-lit" }, String(i + 1))); });
        host.append(svg, h("div", { class: "vrow" }, h("span", { class: "small muted" }, "output:"), ...f.seen.map((n, i) => chip(String(n.v), i === f.seen.length - 1 ? "lit" : "mint"))));
      }, 800);
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- BFS / DFS grid
  add({
    id: "grid-bfs-dfs",
    title: "BFS vs DFS on a grid",
    blurb: "Tap cells to add walls, then search",
    nodes: ["dsa-graphs"],
    mount(root, ctx) {
      const C = 10, R = 7, start = [0, 0], goal = [9, 6];
      let walls = new Set(["3,0", "3,1", "3,2", "3,3", "6,3", "6,4", "6,5", "6,6", "1,5", "2,5", "8,1", "8,2"]);
      let mode = "bfs", timer = null, shown = 0, result = null;
      const halt = () => { ctx.clear(timer); timer = null; };
      const grid = h("div", { style: `display:grid;grid-template-columns:repeat(${C},1fr);gap:3px;max-width:520px;width:100%;margin:0 auto;touch-action:manipulation` });
      const stats = h("div", { class: "vstats" });
      const cap = caption("Breadth-first search explores in rings using a queue. Depth-first search dives down one path using a stack.");
      function search() {
        const key = (x, y) => x + "," + y, prev = new Map(), visited = [], seen = new Set([key(...start)]);
        const box = [start];
        while (box.length) {
          const [x, y] = mode === "bfs" ? box.shift() : box.pop();
          visited.push(key(x, y));
          if (x === goal[0] && y === goal[1]) break;
          [[1, 0], [0, 1], [-1, 0], [0, -1]].forEach(([dx, dy]) => { const nx = x + dx, ny = y + dy, k = key(nx, ny); if (nx < 0 || ny < 0 || nx >= C || ny >= R || walls.has(k) || seen.has(k)) return; seen.add(k); prev.set(k, key(x, y)); box.push([nx, ny]); });
        }
        const path = []; let cur = key(...goal);
        if (prev.has(cur)) { while (cur) { path.unshift(cur); cur = prev.get(cur); } }
        return { visited, path };
      }
      function draw() {
        clear(grid);
        const vis = result ? result.visited.slice(0, shown) : [];
        const done = result && shown >= result.visited.length;
        const onPath = new Set(done ? result.path : []);
        for (let y = 0; y < R; y++) for (let x = 0; x < C; x++) {
          const k = x + "," + y, isS = x === start[0] && y === start[1], isG = x === goal[0] && y === goal[1];
          const vi = vis.indexOf(k);
          const bg = isS ? "var(--plum)" : isG ? "var(--danger)" : walls.has(k) ? "repeating-linear-gradient(45deg, var(--ink-3) 0 3px, var(--bg-sunk) 3px 6px)" : onPath.has(k) ? "var(--lit)" : vi >= 0 ? `color-mix(in srgb, var(--sky) ${Math.max(25, 85 - vi)}%, var(--bg-raised))` : "var(--bg-raised)";
          const cell = h("button", { type: "button", "aria-label": `cell ${x},${y}${walls.has(k) ? " wall" : ""}`, style: `aspect-ratio:1;border:1px solid var(--line);border-radius:4px;background:${bg};padding:0;cursor:pointer;font:0.55rem var(--f-code);color:var(--ink)` }, isS ? "S" : isG ? "G" : "");
          cell.addEventListener("click", () => { if (isS || isG) return; halt(); if (walls.has(k)) walls.delete(k); else walls.add(k); result = null; draw(); });
          grid.appendChild(cell);
        }
        clear(stats).append(stat("cells explored", vis.length), stat("path length", done ? (result.path.length ? result.path.length - 1 : "no path") : "–", done && result.path.length ? "lit" : ""));
      }
      function run() {
        halt(); result = search(); shown = 0;
        timer = ctx.every(() => { if (!result) { halt(); return; } shown++; draw(); if (shown >= result.visited.length) { ctx.clear(timer); cap.textContent = !result.path.length ? "The goal is walled off. Both searches explore everything reachable and give up." : mode === "bfs" ? `BFS found the shortest path (${result.path.length - 1} steps) because it reaches every cell at distance d before any cell at distance d+1. Use BFS for shortest paths in unweighted graphs.` : `DFS found A path (${result.path.length - 1} steps), not necessarily the shortest. It's simpler with recursion and great for "is it connected?", cycle detection and backtracking.`; } }, 45);
      }
      const sg = seg([{ v: "bfs", label: "BFS (queue)" }, { v: "dfs", label: "DFS (stack)" }], mode, (v) => { halt(); mode = v; result = null; draw(); }, "Algorithm");
      root.append(sg.el, row(button("Search", run, { lit: true }), button("Clear walls", () => { halt(); walls = new Set(); result = null; draw(); })), grid, stats, cap);
      draw();
    },
  });

  // ---------------------------------------------------------------- heap
  add({
    id: "min-heap",
    title: "Min-heap: insert and extract",
    blurb: "A tree stored inside an array",
    nodes: ["dsa-heaps"],
    mount(root, ctx) {
      let heap = [3, 8, 5, 12, 10, 9];
      let F = [{ a: heap.slice(), hl: [], say: "Parent of index i is (i-1)/2, children are 2i+1 and 2i+2. Every parent is smaller than its children, so the minimum is always at index 0." }];
      function insert(v) {
        const a = heap.slice(); a.push(v); let i = a.length - 1;
        F = [{ a: a.slice(), hl: [i], say: `Insert ${v} at the end (keeps the tree complete).` }];
        while (i > 0) { const p = (i - 1) >> 1; if (a[p] <= a[i]) { F.push({ a: a.slice(), hl: [i, p], say: `${a[i]} ≥ parent ${a[p]}. Heap property holds. Done in O(log n).` }); break; } F.push({ a: a.slice(), hl: [i, p], say: `${a[i]} < parent ${a[p]}: swap (sift up).` }); [a[p], a[i]] = [a[i], a[p]]; i = p; F.push({ a: a.slice(), hl: [i], say: `${a[i]} moved up to index ${i}.` }); }
        if (i === 0) F.push({ a: a.slice(), hl: [0], say: `${a[0]} reached the root. It's the new minimum.` });
        heap = a; st.go(0);
      }
      function extract() {
        if (!heap.length) return;
        const a = heap.slice(), min = a[0];
        F = [{ a: a.slice(), hl: [0], say: `Remove the min (${min}) from the root.` }];
        const last = a.pop(); if (!a.length) { heap = a; F.push({ a: [], hl: [], say: "Heap is empty." }); st.go(0); return; }
        a[0] = last; F.push({ a: a.slice(), hl: [0], say: `Move the last element (${last}) to the root.` });
        let i = 0;
        for (;;) { const l = 2 * i + 1, r = l + 1; let m = i; if (l < a.length && a[l] < a[m]) m = l; if (r < a.length && a[r] < a[m]) m = r; if (m === i) { F.push({ a: a.slice(), hl: [i], say: `${a[i]} is smaller than its children. Done: O(log n). Returned ${min}.` }); break; } F.push({ a: a.slice(), hl: [i, m], say: `${a[i]} > smaller child ${a[m]}: swap (sift down).` }); [a[i], a[m]] = [a[m], a[i]]; i = m; }
        heap = a; st.go(0);
      }
      const ctrl = row(button("Insert random", () => { st.stop(); insert(1 + Math.floor(Math.random() * 20)); st.start(); }, { lit: true }), button("Insert 1", () => { st.stop(); insert(1); st.start(); }), button("Extract min", () => { st.stop(); extract(); st.start(); }));
      root.appendChild(ctrl);
      const st = frames(root, ctx, () => F, (host, f) => {
        const svg = s("svg", { class: "vsvg", viewBox: "0 0 340 180", style: "max-width:480px;margin:0 auto", role: "img", "aria-label": "Heap as a tree" });
        const pos = (i) => { const d = Math.floor(Math.log2(i + 1)), k = i - (Math.pow(2, d) - 1); return [((k + 0.5) / Math.pow(2, d)) * 340, 22 + d * 50]; };
        f.a.forEach((_, i) => { if (!i) return; const [x1, y1] = pos((i - 1) >> 1), [x2, y2] = pos(i); svg.appendChild(s("line", { x1, y1, x2, y2, class: "s-line", "stroke-width": 2 })); });
        f.a.forEach((v, i) => { const [x, y] = pos(i); const hl = f.hl.includes(i); svg.appendChild(s("circle", { cx: x, cy: y, r: 15, class: hl ? "f-lit" : i === 0 ? "f-mint" : "f-raised s-line", "stroke-width": 1.5 })); svg.appendChild(s("text", { x, y: y + 5, "text-anchor": "middle", "font-size": 13, "font-weight": 700, class: hl || i === 0 ? "t-ink-on-lit" : "" }, String(v))); });
        const cls = {}; f.hl.forEach((i) => (cls[i] = "lit"));
        host.append(svg, strip(f.a.length ? f.a : ["–"], { cls }));
      }, 1000);
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- DP table
  add({
    id: "dp-lcs",
    title: "Dynamic programming table: LCS",
    blurb: "Longest common subsequence, filled cell by cell",
    nodes: ["dsa-dp"],
    mount(root, ctx) {
      let A = "TRAIN", B = "BRAIN";
      let F = [];
      function gen() {
        const n = A.length, m = B.length, dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
        F = [{ dp: dp.map((r) => r.slice()), cur: null, deps: [], path: [], say: "dp[i][j] = LCS length of the first i letters of A and the first j letters of B. Row 0 and column 0 are 0 (an empty string shares nothing)." }];
        for (let i = 1; i <= n; i++) for (let j = 1; j <= m; j++) {
          if (A[i - 1] === B[j - 1]) { dp[i][j] = dp[i - 1][j - 1] + 1; F.push({ dp: dp.map((r) => r.slice()), cur: [i, j], deps: [[i - 1, j - 1]], path: [], match: true, say: `${A[i - 1]} = ${B[j - 1]}: match! Take the diagonal and add 1 → ${dp[i][j]}.` }); }
          else { dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); F.push({ dp: dp.map((r) => r.slice()), cur: [i, j], deps: [[i - 1, j], [i, j - 1]], path: [], say: `${A[i - 1]} ≠ ${B[j - 1]}: best of dropping a letter from A (above) or from B (left) → ${dp[i][j]}.` }); }
        }
        const path = []; let i = n, j = m, out = "";
        while (i > 0 && j > 0) { if (A[i - 1] === B[j - 1]) { path.push([i, j]); out = A[i - 1] + out; i--; j--; } else if (dp[i - 1][j] >= dp[i][j - 1]) i--; else j--; }
        F.push({ dp: dp.map((r) => r.slice()), cur: null, deps: [], path, final: true, say: `Answer dp[${n}][${m}] = ${dp[n][m]}: "${out}". Walk back through the matches to recover it. Each cell is computed once from its neighbours: O(n·m) instead of trying every subsequence (exponential).` });
      }
      gen();
      const sg = seg([["TRAIN", "BRAIN"], ["ABCBD", "BDCAB"], ["KARMA", "DHARMA"]].map(([a, b]) => ({ v: a + "|" + b, label: `${a} / ${b}` })), A + "|" + B, (v) => { [A, B] = v.split("|"); gen(); st.stop(); st.go(0); }, "Strings");
      root.appendChild(sg.el);
      const st = frames(root, ctx, () => F, (host, f) => {
        const cell = (txt, style) => h("div", { style: "aspect-ratio:1;display:grid;place-items:center;border-radius:4px;font:700 0.82rem var(--f-code);" + (style || "") }, txt);
        const g = h("div", { style: `display:grid;grid-template-columns:repeat(${B.length + 2},minmax(26px,1fr));gap:3px;max-width:${(B.length + 2) * 46}px` });
        g.append(cell(""), cell("∅", "color:var(--ink-3)"), ...B.split("").map((c) => cell(c, "color:var(--sky)")));
        for (let i = 0; i <= A.length; i++) {
          g.appendChild(cell(i ? A[i - 1] : "∅", i ? "color:var(--plum)" : "color:var(--ink-3)"));
          for (let j = 0; j <= B.length; j++) {
            const cur = f.cur && f.cur[0] === i && f.cur[1] === j;
            const dep = f.deps.some(([a, b]) => a === i && b === j);
            const onPath = f.path.some(([a, b]) => a === i && b === j);
            const filled = f.final || i === 0 || j === 0 || (f.cur && (i < f.cur[0] || (i === f.cur[0] && j <= f.cur[1])));
            const bg = cur ? (f.match ? "var(--mint)" : "var(--lit)") : onPath ? "var(--mint)" : dep ? "var(--lit-soft)" : "var(--bg-raised)";
            g.appendChild(cell(filled ? String(f.dp[i][j]) : "", `background:${bg};border:1px solid ${dep ? "var(--lit)" : "var(--line)"};${cur || onPath ? "color:var(--lit-ink)" : ""}`));
          }
        }
        host.append(h("div", { class: "vscroll" }, g));
      }, 700);
      st.go(0);
    },
  });

  // ---------------------------------------------------------------- intervals
  add({
    id: "merge-intervals",
    title: "Merge overlapping intervals",
    blurb: "Sort by start, then sweep once",
    nodes: ["dsa-intervals"],
    mount(root, ctx) {
      const input = [[8, 10], [1, 3], [15, 18], [2, 6], [9, 12], [17, 20]];
      const sorted = input.slice().sort((a, b) => a[0] - b[0]);
      const F = [{ list: input, merged: [], cur: -1, say: "Unsorted, overlaps are hard to spot. Step one: sort by start time. O(n log n)." }, { list: sorted, merged: [], cur: -1, say: "Sorted by start. Now any interval can only overlap the one merged just before it." }];
      const merged = [];
      sorted.forEach((iv, i) => {
        const last = merged[merged.length - 1];
        if (last && iv[0] <= last[1]) { const before = last.slice(); last[1] = Math.max(last[1], iv[1]); F.push({ list: sorted, merged: merged.map((m) => m.slice()), cur: i, say: `[${iv}] starts at ${iv[0]} ≤ ${before[1]}, the end of [${before}]. Overlap: extend to [${last}].` }); }
        else { merged.push(iv.slice()); F.push({ list: sorted, merged: merged.map((m) => m.slice()), cur: i, say: last ? `[${iv}] starts after ${last[1]}. No overlap: start a new interval.` : `First interval [${iv}] starts the output.` }); }
      });
      F.push({ list: sorted, merged: merged.map((m) => m.slice()), cur: -1, say: `Result: ${merged.map((m) => `[${m}]`).join(" ")}. Calendar booking, meeting rooms and insert-interval are all variations of this sweep.` });
      const st = frames(root, ctx, () => F, (host, f) => {
        const max = 21, W = 340;
        const svg = s("svg", { class: "vsvg", viewBox: `0 0 ${W} ${f.list.length * 20 + 70}`, style: "max-width:560px", role: "img", "aria-label": "Intervals on a number line" });
        const x = (v) => 10 + (v / max) * (W - 20);
        for (let v = 0; v <= 20; v += 2) { svg.appendChild(s("line", { x1: x(v), x2: x(v), y1: 0, y2: f.list.length * 20 + 40, class: "s-line", "stroke-width": 0.5 })); svg.appendChild(s("text", { x: x(v), y: f.list.length * 20 + 64, "font-size": 9, "text-anchor": "middle", class: "t-dim" }, String(v))); }
        f.list.forEach((iv, i) => svg.appendChild(s("rect", { x: x(iv[0]), y: 4 + i * 20, width: x(iv[1]) - x(iv[0]), height: 14, rx: 4, class: i === f.cur ? "f-lit" : "f-sky", opacity: f.cur >= 0 && i > f.cur ? 0.4 : 0.85 })));
        f.merged.forEach((iv) => svg.appendChild(s("rect", { x: x(iv[0]), y: f.list.length * 20 + 18, width: x(iv[1]) - x(iv[0]), height: 16, rx: 4, class: "f-mint" })));
        svg.appendChild(s("text", { x: 10, y: f.list.length * 20 + 14, "font-size": 9, class: "t-dim" }, "merged ↓"));
        host.append(svg);
      }, 1300);
      st.go(0);
    },
  });
})();
